import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{matchingRule,movementResult}from'../core.js';import{matchingPhotographs}from'../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),refs=['CAZ1019','CAZ1013','CAZ101K'],rules=read('research-updates-20261008.json').filter(r=>r.brand==='TAGHEUER'&&refs.includes(r.baseReference)),photos=read('photographs.json').photographs.filter(p=>p.id.startsWith('tag-caz1019-20261026-'));
test('Formula 1 guidance keeps supplier execution evidence reference-specific',()=>{assert.equal(rules.length,3);assert.equal(movementResult(matchingRule(rules,'TAG Heuer','CAZ1019'),'5040.D').level,'match');const k=matchingRule(rules,'TAG Heuer','CAZ101K');assert.equal(k.researchStatus,'needs_evidence');assert.equal(movementResult(k,'5040.D').level,'caution');assert.ok(rules.every(r=>r.manualReview&&r.exactReferenceOnly));for(const ref of ['CAZ1012','CAZ1015','WAZ1019','CAZ101K.BA0883','CAZ1019.BA0842'])assert.equal(matchingRule(rules,'TAG Heuer',ref),null);});
test('Senna specimen images match only documented rubber-strap execution',()=>{assert.equal(photos.length,3);for(const ref of ['CAZ1019','CAZ1019.FT8027'])assert.equal(matchingPhotographs(photos,'TAG Heuer',ref).length,3);assert.equal(matchingPhotographs(photos,'TAG Heuer','CAZ1019',{externalOnly:true}).length,3);assert.ok(photos.every(p=>!p.depictsMovement&&p.category!=='movement'));for(const ref of ['CAZ1013','CAZ101K','CAZ1019.FT8028','CAZ1019.BA0842'])assert.equal(matchingPhotographs(photos,'TAG Heuer',ref).length,0);assert.match(photos.find(p=>p.category==='caseback').caption,/source-redacted serial/);});
test('Unresolved CAZ101K fitted movement question remains explicit',()=>{const rows=read('research-queue-tag-formula-20261026-sources.json').records;assert.equal(rows.find(r=>r.reference==='CAZ101K').decision,'needs_evidence');assert.match(rows.find(r=>r.reference==='CAZ101K').conclusion,/Keep the movement question active/);assert.ok(rows.find(r=>r.reference==='CAZ1019').unsupported.includes('movement'));});
